package com.crm.product.controller;
import com.crm.product.entity.Product; import com.crm.product.repository.ProductRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/products") public class ProductController { private final ProductRepository repo; public ProductController(ProductRepository repo){this.repo=repo;} @GetMapping public List<Product> all(){return repo.findAll();} @GetMapping("/{id}") public ResponseEntity<Product> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public ResponseEntity<Product> create(@RequestBody Product x){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(x));} @PutMapping("/{id}") public ResponseEntity<Product> update(@PathVariable Long id,@RequestBody Product x){return repo.findById(id).map(e->{e.setName(x.getName());e.setSku(x.getSku());e.setDescription(x.getDescription());e.setPrice(x.getPrice());e.setActive(x.isActive());return ResponseEntity.ok(repo.save(e));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }